const RESULTS_EVENT = 'addon.thsv.free-game-check.results';
const DISCORD_RESULT_EVENT = 'addon.thsv.free-game-check.discord-result'; const DISCORD_ACTION_ID = '7e9b4db8-5d33-4ed2-a8d1-11f8d04ab662';
let taskId; let stopped = true; let operation = Promise.resolve(); let activeRequestId = ''; const pendingDiscord = new Map();
const manifest = { contractVersion:'2.0.0-preview.1',moduleId:MODULE_ID,name:'Free Game Check',version:'3.0.0',minimumCoreVersion:'2.0.0-preview.1',maximumTestedCoreVersion:'2.0.0-preview.1', minimumBridgeVersion: '3.0.0', maximumTestedBridgeVersion: '3.0.0',dependencies:[],requiredCapabilities:[],configurationSchema:'schemas/config.json',eventSubscriptions:[RESULTS_EVENT,DISCORD_RESULT_EVENT,'reward.redemption','command.received','chat.message'],commandsProvided:[{id:'free-game-check.command',name:'freegames'}],actionsProvided:[{id:'free-game-check.refresh',name:'THSV Addon - Free Game Check - Refresh'},{id:'free-game-check.discord',name:'THSV Addon - Free Game Check - Discord Deliver'}],browserSourcesProvided:[],dataStorageOwned:['data/addons/thsv.free-game-check/','data/addons/.state/thsv.free-game-check/'],installationSteps:['Import the Free Game Check Streamer.bot package and leave both actions triggerless.','Approve Refresh and, only when Discord is enabled, Discord Deliver. Keep the private webhook only in its Set Argument.','Create Twitch and Kick Free Games rewards and paste their stable IDs. Keep one Reward Redemption trigger on each existing platform intake.','Create the configured no-response command for YouTube and TikTok through Command Sync.','Add the Discord invite and guide wording, then enable the add-on.'],uninstallationSteps:['Uninstalling preserves only bounded giveaway IDs, cooldowns, and refresh/delivery status.'],migrations:[],healthChecks:[{id:'thsv.free-game-check.runtime',description:'Confirms bounded public giveaway discovery and source-routed viewer guidance are available.'}] };
function text(value,max=500){return[...(typeof value==='string'?value.replace(/[\u0000-\u001f\u007f]/gu,' ').replace(/\s+/gu,' ').trim():'')].slice(0,max).join('');}
function safeDiscordInvite(value){const candidate=text(value,160);if(!candidate)return'';try{const parsed=new URL(candidate);const host=parsed.hostname.toLowerCase();if(parsed.protocol!=='https:'||!['discord.gg','discord.com'].includes(host))return'';if(host==='discord.com'&&!parsed.pathname.startsWith('/invite/'))return'';return parsed.href;}catch{return'';}}
function settingsFor(context){const raw=context.settings||{};const platforms=Array.isArray(raw.deliveryPlatforms)?raw.deliveryPlatforms.filter((item)=>['twitch','youtube','kick','tiktok'].includes(item)).slice(0,4):[];return{enabled:raw.enabled===true,rewardId:text(raw.rewardId,256),kickRewardId:text(raw.kickRewardId,256),commandName:text(raw.commandName,64).toLowerCase()||'freegames',discordInviteUrl:safeDiscordInvite(raw.discordInviteUrl),guideMessage:text(raw.guideMessage,350)||'{name}, our current free-game list is in Discord: {discord}',guideCooldownMinutes:Number.isInteger(raw.guideCooldownMinutes)?Math.min(1440,Math.max(1,raw.guideCooldownMinutes)):10,refreshMinutes:Number.isInteger(raw.refreshMinutes)?Math.min(1440,Math.max(60,raw.refreshMinutes)):180,maximumPostsPerRefresh:Number.isInteger(raw.maximumPostsPerRefresh)?Math.min(5,Math.max(1,raw.maximumPostsPerRefresh)):2,announceInitial:raw.announceInitial===true,deliveryPlatforms:platforms,discordEnabled:raw.discordEnabled===true,discordMode:raw.discordDestinationMode==='forum'?'forum':'channel',discordThreadId:/^[0-9]{5,30}$/u.test(text(raw.discordThreadId,30))?text(raw.discordThreadId,30):'',discordThreadName:text(raw.discordThreadName,100)||'Free Game - {title}',discordWebhookName:text(raw.discordWebhookName,80)||'THSV Free Game Check'};}
function validGame(raw){const id=text(raw?.id,80);const title=text(raw?.title,160);const url=text(raw?.url,500);let parsed;try{parsed=new URL(url);}catch{return undefined;}if(!id||!title||parsed.protocol!=='https:'||!['gamerpower.com','www.gamerpower.com'].includes(parsed.hostname.toLowerCase()))return undefined;return{id,title,url:parsed.href,platforms:text(raw?.platforms,120),endDate:text(raw?.endDate,80)};}
function stateFor(raw){const value=raw&&typeof raw==='object'?raw:{};const delivery=value.lastDiscordDelivery&&typeof value.lastDiscordDelivery==='object'?value.lastDiscordDelivery:undefined;const guideCooldowns=value.guideCooldowns&&typeof value.guideCooldowns==='object'?Object.fromEntries(Object.entries(value.guideCooldowns).map(([key,at])=>[text(key,280),Number.isFinite(at)?at:0]).filter(([key,at])=>key&&at>0).sort((left,right)=>left[1]-right[1]).slice(-500)):{};return{initialized:value.initialized===true,seenIds:Array.isArray(value.seenIds)?value.seenIds.map((item)=>text(item,80)).filter(Boolean).slice(-1000):[],guideCooldowns,lastRefreshAt:text(value.lastRefreshAt,40),lastError:text(value.lastError,180),...(delivery?{lastDiscordDelivery:{at:text(delivery.at,40),success:delivery.success===true,messageId:text(delivery.messageId,100),threadId:text(delivery.threadId,100),error:text(delivery.error,180)}}:{})};}
async function arm(context,delay){if(taskId)context.schedule.cancel(taskId);taskId=context.schedule.after(delay,()=>{taskId=undefined;return serialize(()=>refresh(context));});}
async function refresh(context){const settings=settingsFor(context);if(stopped||!settings.enabled)return;activeRequestId=`free-game-${Date.now()}-${Math.random().toString(36).slice(2,10)}`;try{await context.streamerbot.runApprovedAction(REFRESH_ACTION_ID,{freeGameCheckRequestId:activeRequestId});}catch{activeRequestId='';const state=stateFor(await context.state.read());await context.state.write({...state,lastError:'The approved giveaway refresh could not be dispatched.'});}await arm(context,settings.refreshMinutes*60_000);}
async function processResults(event,context){const settings=settingsFor(context);const requestId=text(event.payload?.requestId,100);if(!settings.enabled||event.platform!=='system'||event.metadata?.simulated===true||!activeRequestId||requestId!==activeRequestId)return;activeRequestId='';const state=stateFor(await context.state.read());const wasInitialized=state.initialized;const rawGames=Array.isArray(event.payload?.games)?event.payload.games.slice(0,100):[];const games=rawGames.map(validGame).filter(Boolean);if(rawGames.length>0&&games.length===0){state.lastError='The giveaway provider returned entries without safe GamerPower links.';await context.state.write(state);return;}const known=new Set(state.seenIds);const fresh=games.filter((game)=>!known.has(game.id));for(const game of games)known.add(game.id);state.initialized=true;state.seenIds=[...known].slice(-1000);state.lastRefreshAt=text(event.receivedAt,40);state.lastError='';await context.state.write(state);if(!settings.announceInitial&&!wasInitialized)return;for(const game of fresh.slice(0,settings.maximumPostsPerRefresh)){const message=`Free game: ${game.title}${game.platforms?` (${game.platforms})`:''} ${game.url} - Powered by GamerPower.com`;if(settings.deliveryPlatforms.length)try{await context.chat.send({message,routing:'selected',selectedPlatforms:settings.deliveryPlatforms,overflow:'truncate'});}catch{/* A provider send failure must not replay the same giveaway forever. */}if(settings.discordEnabled){const deliveryId=`game-${Date.now()}-${Math.random().toString(36).slice(2,10)}`;pendingDiscord.set(deliveryId,Date.now()+60_000);if(pendingDiscord.size>20)pendingDiscord.delete(pendingDiscord.keys().next().value);try{await context.streamerbot.runApprovedAction(DISCORD_ACTION_ID,{freeGameDiscordDeliveryId:deliveryId,freeGameDiscordTitle:game.title,freeGameDiscordUrl:game.url,freeGameDiscordPlatforms:game.platforms,freeGameDiscordEndDate:game.endDate,freeGameDiscordDestinationMode:settings.discordMode,freeGameDiscordThreadId:settings.discordThreadId,freeGameDiscordThreadName:settings.discordThreadName.replaceAll('{title}',game.title).slice(0,100),freeGameDiscordWebhookName:settings.discordWebhookName});}catch{pendingDiscord.delete(deliveryId);}}}}
async function processDiscordResult(event,context){const id=text(event.payload?.deliveryId,100);const expires=pendingDiscord.get(id);if(!expires||expires<Date.now()){pendingDiscord.delete(id);return;}pendingDiscord.delete(id);const state=stateFor(await context.state.read());state.lastDiscordDelivery={at:text(event.receivedAt,40),success:event.payload?.success===true,messageId:text(event.payload?.messageId,100),threadId:text(event.payload?.threadId,100),error:text(event.payload?.error,180)};await context.state.write(state);}
function formatGuide(template,values){let result=text(template,700);for(const[key,value]of Object.entries(values))result=result.replaceAll(`{${key}}`,text(String(value),200));return text(result,500);}
async function processViewerGuide(event,context){const settings=settingsFor(context);if(!settings.enabled||event.metadata?.simulated===true)return;const configuredReward=event.platform==='twitch'?settings.rewardId:event.platform==='kick'?settings.kickRewardId:'';const matchingReward=event.eventType==='reward.redemption'&&['twitch','kick'].includes(event.platform)&&event.payload?.verifiedTransport===true&&configuredReward&&text(event.payload?.rewardId,256)===configuredReward;const command=text(event.payload?.command,64).toLowerCase();const chatMessage=text(event.payload?.message,520).toLowerCase();const commandPhrase=`!${settings.commandName}`;const matchingCommand=['youtube','tiktok'].includes(event.platform)&&((event.eventType==='command.received'&&command===settings.commandName)||(event.eventType==='chat.message'&&(chatMessage===commandPhrase||chatMessage.startsWith(`${commandPhrase} `))));if(!matchingReward&&!matchingCommand)return;const userId=text(event.user?.id,240);const displayName=text(event.user?.displayName||event.user?.name,100)||'Villager';if(!userId)return;const state=stateFor(await context.state.read());if(!settings.discordInviteUrl){state.lastError='Add a valid Discord invite before enabling viewer Free Games requests.';await context.state.write(state);return;}const now=Date.now();const key=`${event.platform}:${userId}`;const last=state.guideCooldowns[key]||0;if(now-last<settings.guideCooldownMinutes*60_000)return;state.guideCooldowns=Object.fromEntries(Object.entries({...state.guideCooldowns,[key]:now}).sort((left,right)=>left[1]-right[1]).slice(-500));state.lastError='';await context.state.write(state);const message=formatGuide(settings.guideMessage,{name:displayName,discord:settings.discordInviteUrl});if(!message)return;try{await context.chat.send({message,routing:'source',sourcePlatform:event.platform,overflow:'truncate'});}catch{/* A source-chat send failure must not create an unbounded retry loop. */}}
function serialize(work){operation=operation.then(work,work);return operation;}
export default{manifest,required:false,async start(context){stopped=false;activeRequestId='';pendingDiscord.clear();operation=Promise.resolve();await context.state.write(stateFor(await context.state.read()));if(settingsFor(context).enabled)await arm(context,1500);},async stop(context){stopped=true;activeRequestId='';pendingDiscord.clear();if(taskId)context.schedule.cancel(taskId);taskId=undefined;await operation.catch(()=>undefined);operation=Promise.resolve();},async onEvent(event,context){if(event.eventType===RESULTS_EVENT)await serialize(()=>processResults(event,context));else if(event.eventType===DISCORD_RESULT_EVENT&&event.platform==='system'&&event.metadata?.simulated!==true)await serialize(()=>processDiscordResult(event,context));else if(['reward.redemption','command.received','chat.message'].includes(event.eventType))await serialize(()=>processViewerGuide(event,context));}};
export{RESULTS_EVENT,DISCORD_RESULT_EVENT,stateFor,validGame,safeDiscordInvite,processViewerGuide};
